CREATE OR REPLACE FUNCTION app_private.user_can_manage_client(_user_id uuid, _client_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when auth.uid() is not null and _user_id is distinct from auth.uid() then false else (
  SELECT EXISTS (
    SELECT 1
    FROM public.clients c
    WHERE c.id = _client_id
      AND (
        c.owner_user_id = _user_id
        OR (c.firm_id IS NOT NULL AND app_private.has_firm_access(_user_id, c.firm_id))
        OR (
          app_private.is_super_admin(_user_id)
          AND app_private.platform_staff_can_access_firm(_user_id, c.firm_id)
        )
      )
  )
  ) end
$function$
;
CREATE OR REPLACE FUNCTION app_private.user_can_read_client(_user_id uuid, _client_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when auth.uid() is not null and _user_id is distinct from auth.uid() then false else (
  SELECT app_private.user_can_manage_client(_user_id, _client_id)
      OR app_private.has_client_access(_user_id, _client_id)
      OR EXISTS (
        SELECT 1 FROM public.clients c
        WHERE c.id = _client_id
          AND c.firm_id IS NOT NULL
          AND app_private.has_firm_access(_user_id, c.firm_id)
      )
  ) end
$function$
;
CREATE OR REPLACE FUNCTION app_private.shares_firm_with(_viewer uuid, _subject uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when auth.uid() is not null and _viewer is distinct from auth.uid() then false else (
  select exists (
    select 1
    from public.firm_members vm
    join public.firm_members sm on sm.firm_id = vm.firm_id
    where vm.user_id = _viewer and vm.status = 'active'
      and sm.user_id = _subject and sm.status = 'active'
  )
  ) end
$function$
;
CREATE OR REPLACE FUNCTION app_private.move_xero_file_to_client(_connection_id uuid, _target_client_id uuid, _actor_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'app_private'
AS $function$
DECLARE
  v_source_client_id uuid;
  v_source_firm_id uuid;
  v_target_firm_id uuid;
BEGIN
  IF NOT app_private.user_can_write_client(_actor_user_id, _target_client_id) THEN RAISE EXCEPTION 'You cannot manage the target client subscription'; END IF;
  SELECT cxo.client_id, c.firm_id INTO v_source_client_id, v_source_firm_id
  FROM public.client_xero_orgs cxo JOIN public.clients c ON c.id = cxo.client_id
  WHERE cxo.xero_connection_id = _connection_id FOR UPDATE OF cxo;
  SELECT firm_id INTO v_target_firm_id FROM public.clients WHERE id = _target_client_id;
  IF v_source_client_id IS NULL THEN RAISE EXCEPTION 'That Xero file is no longer linked to another subscription'; END IF;
  IF v_source_client_id = _target_client_id THEN RAISE EXCEPTION 'That Xero file is already linked to this subscription'; END IF;
  IF v_source_firm_id IS DISTINCT FROM v_target_firm_id AND NOT app_private.is_super_admin(_actor_user_id) THEN RAISE EXCEPTION 'Only a platform admin can move a Xero file between organisations'; END IF;
  IF NOT app_private.is_super_admin(_actor_user_id) AND NOT app_private.user_can_write_client(_actor_user_id, v_source_client_id) THEN RAISE EXCEPTION 'You cannot manage the subscription that currently holds this Xero file'; END IF;
  DELETE FROM public.client_xero_orgs WHERE xero_connection_id = _connection_id;
  INSERT INTO public.client_xero_orgs (client_id, xero_connection_id) VALUES (_target_client_id, _connection_id);
  UPDATE public.xero_connections SET firm_id = v_target_firm_id WHERE id = _connection_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION app_private.platform_staff_can_access_firm(_user_id uuid, _firm_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when auth.uid() is not null and _user_id is distinct from auth.uid() then false else (
  select _firm_id is not null
     and app_private.is_super_admin(_user_id)
     and app_private.firm_support_access_active(_user_id, _firm_id)
  ) end
$function$
;
CREATE OR REPLACE FUNCTION app_private.firm_support_access_active(_user_id uuid, _firm_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when auth.uid() is not null and _user_id is distinct from auth.uid() then false else (
  select exists (
    select 1 from public.firm_support_access fsa
    where fsa.firm_id = _firm_id
      and fsa.grantee_user_id = _user_id
      and fsa.granted = true
      and fsa.revoked_at is null
      and fsa.expires_at > now()
  )
  ) end
$function$
;
CREATE OR REPLACE FUNCTION app_private.firm_ids_for_tenant(_tenant_id text)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select xc.firm_id from public.xero_connections xc
   where xc.tenant_id = _tenant_id and xc.firm_id is not null
  union
  select c.firm_id
    from public.client_xero_orgs cxo
    join public.clients c on c.id = cxo.client_id
    join public.xero_connections xc2 on xc2.id = cxo.xero_connection_id
   where xc2.tenant_id = _tenant_id and c.firm_id is not null
$function$
;
CREATE OR REPLACE FUNCTION app_private.user_can_access_tenant(_user_id uuid, _tenant_id text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when auth.uid() is not null and _user_id is distinct from auth.uid() then false else (
  select exists (
    select 1 from app_private.firm_ids_for_tenant(_tenant_id) as f(firm_id)
    where app_private.has_firm_access(_user_id, f.firm_id)
       or app_private.platform_staff_can_access_firm(_user_id, f.firm_id)
  )
  ) end
$function$
;
CREATE OR REPLACE FUNCTION public.user_can_access_firm(_user_id uuid, _firm_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select app_private.assert_aal2();

  select case when auth.uid() is not null and _user_id is distinct from auth.uid() then false else (
  select _user_id is not null and _firm_id is not null
     and (app_private.has_firm_access(_user_id, _firm_id)
       or app_private.platform_staff_can_access_firm(_user_id, _firm_id))
  ) end
$function$
;
CREATE OR REPLACE FUNCTION public.user_can_access_client(_user_id uuid, _client_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select app_private.assert_aal2();

  select case when auth.uid() is not null and _user_id is distinct from auth.uid() then false else (
  select exists (
    select 1 from public.clients c
    where c.id = _client_id
      and (public.user_can_access_firm(_user_id, c.firm_id)
        or app_private.has_client_access(_user_id, c.id))
  )
  ) end
$function$
;
CREATE OR REPLACE FUNCTION app_private.is_org_owner(_user_id uuid, _firm_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when auth.uid() is not null and _user_id is distinct from auth.uid() then false else (
  select exists (select 1 from public.firms f
                 where f.id = _firm_id and f.owner_user_id = _user_id)
      or app_private.is_firm_owner(_user_id, _firm_id)
  ) end
$function$
;
CREATE OR REPLACE FUNCTION public.client_entitlement(_client_id uuid)
 RETURNS TABLE(tier dashboard_tier, source text, expires_at timestamp with time zone, in_grace boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'app_private'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _firm uuid;
  _always_free boolean := false;
  _sub public.client_subscriptions%ROWTYPE;
  _tier public.dashboard_tier := 'basic';
  _source text := 'none';
  _expires timestamptz := NULL;
  _grace boolean := false;
  _top public.dashboard_tier;
BEGIN
  perform app_private.assert_aal2();
  IF _uid IS NULL OR NOT app_private.user_can_read_client(_uid, _client_id) THEN
    RETURN QUERY SELECT 'basic'::public.dashboard_tier, 'none'::text, NULL::timestamptz, false;
    RETURN;
  END IF;

  SELECT c.firm_id INTO _firm FROM public.clients c WHERE c.id = _client_id;
  IF _firm IS NOT NULL THEN
    SELECT f.is_always_free INTO _always_free FROM public.firms f WHERE f.id = _firm;
  END IF;

  -- Organisation lapsed: Standard only, whatever the client row says.
  IF _firm IS NOT NULL AND app_private.firm_subscription_lapsed(_firm) THEN
    RETURN QUERY SELECT 'basic'::public.dashboard_tier, 'org_lapsed'::text, NULL::timestamptz, false;
    RETURN;
  END IF;

  SELECT * INTO _sub FROM public.client_subscriptions s
   WHERE s.client_id = _client_id ORDER BY s.created_at DESC LIMIT 1;

  IF COALESCE(_always_free, false) THEN
    SELECT l.key::public.dashboard_tier INTO _top
    FROM public.plan_levels l
    LEFT JOIN public.tier_settings ts ON ts.tier = l.key
    WHERE l.scope='dashboard' AND l.enabled AND COALESCE(ts.enabled,true)
      AND l.key IN ('basic','advisory','investigate','multi_company')
    ORDER BY l.sort_order DESC LIMIT 1;
    _tier := COALESCE(_top,'basic'); _source := 'org_always_free';
  ELSIF _sub.id IS NOT NULL THEN
    IF _sub.subscription_type = 'free_forever' THEN
      _tier := COALESCE(_sub.dashboard_tier,'basic'); _source := 'free_forever';
    ELSIF _sub.subscription_type = 'trial' THEN
      IF _sub.trial_end IS NOT NULL AND _sub.trial_end > now() THEN
        _tier := _sub.dashboard_tier; _source := 'trial'; _expires := _sub.trial_end;
      END IF;
    ELSIF _sub.subscription_type = 'paid' THEN
      IF _sub.status IN ('active','trialing','free_forever') THEN
        _tier := _sub.dashboard_tier; _source := 'paid'; _expires := _sub.current_period_end;
      ELSIF _sub.status = 'past_due' AND _sub.current_period_end IS NOT NULL
            AND _sub.current_period_end > now() THEN
        _tier := _sub.dashboard_tier; _source := 'paid';
        _expires := _sub.current_period_end; _grace := true;
      END IF;
    END IF;
  END IF;

  IF _tier <> 'basic' AND EXISTS (
    SELECT 1 FROM public.tier_settings ts WHERE ts.tier = _tier::text AND ts.enabled = false
  ) THEN
    _tier := 'basic'; _source := 'none'; _expires := NULL; _grace := false;
  END IF;

  RETURN QUERY SELECT _tier, _source, _expires, _grace;
END;
$function$
;
CREATE OR REPLACE FUNCTION app_private.firm_limits(_firm_id uuid)
 RETURNS TABLE(client_limit integer, xero_org_limit integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(s.client_limit_override, pl.client_limit), pl.xero_org_limit
  from public.subscriptions s
  left join public.plan_levels pl on pl.scope='firm' and pl.key = s.tier
  where s.firm_id = _firm_id
  limit 1
$function$
;
CREATE OR REPLACE FUNCTION public.transfer_organisation_ownership(_firm_id uuid, _new_owner_user_id uuid, _keep_previous_as_staff boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare _caller uuid := auth.uid(); _prev uuid;
begin
  perform app_private.assert_aal2();
  if _caller is null then
    raise exception 'NOT_AUTHENTICATED' using errcode='insufficient_privilege';
  end if;

  select owner_user_id into _prev from public.firms where id = _firm_id;

  -- only the current owner may hand over
  if not app_private.is_org_owner(_caller, _firm_id) then
    raise exception 'NOT_ORG_OWNER: only the current owner can transfer ownership'
      using errcode='insufficient_privilege';
  end if;

  -- the new owner must already be an active member: no transferring to strangers
  if not exists (select 1 from public.firm_members
                 where firm_id=_firm_id and user_id=_new_owner_user_id and status='active') then
    raise exception 'NOT_A_MEMBER: invite the new owner and have them accept first'
      using errcode='check_violation';
  end if;

  update public.firm_members set role='owner'
   where firm_id=_firm_id and user_id=_new_owner_user_id;

  update public.firms set owner_user_id=_new_owner_user_id where id=_firm_id;

  -- previous owner keeps working access as staff (bookkeeping continues),
  -- or is removed entirely if the client wants us out.
  if _prev is not null and _prev <> _new_owner_user_id then
    if _keep_previous_as_staff then
      update public.firm_members set role='staff'
       where firm_id=_firm_id and user_id=_prev;
    else
      update public.firm_members set status='removed'
       where firm_id=_firm_id and user_id=_prev;
    end if;
  end if;

  insert into public.audit_log (action, firm_id, actor_user_id, target_type, target_id, meta)
  values ('organisation_ownership_transferred', _firm_id, _caller, 'firm', _firm_id::text,
          jsonb_build_object('previous_owner',_prev,'new_owner',_new_owner_user_id,
                             'previous_kept_as_staff',_keep_previous_as_staff));
end $function$
;
