CREATE OR REPLACE FUNCTION public.xero_missing_scopes(_connection_id uuid)
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when not app_private.is_aal2() then null
    when auth.uid() is not null and not exists (
      select 1 from public.xero_connections c
      where c.id = _connection_id
        and c.firm_id is not null
        and (
          app_private.has_firm_access(auth.uid(), c.firm_id)
          or app_private.platform_staff_can_access_firm(auth.uid(), c.firm_id)
        )
    ) then null
    else (
      select coalesce(array_agg(req), '{}')
      from unnest(public.xero_required_scopes()) as req
      where not exists (
        select 1 from public.xero_connections c,
                      unnest(string_to_array(coalesce(c.scopes,''), ' ')) as granted
        where c.id = _connection_id and granted = req
      )
    )
  end
$function$
;
CREATE OR REPLACE FUNCTION public.client_allowed_widgets(_client_id uuid)
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select app_private.assert_aal2();

  select case when auth.uid() is not null
               and not app_private.user_can_read_client(auth.uid(), _client_id)
          then '{}'::text[] else (
  with ent as (select tier::text as tier from public.client_entitlement(_client_id)),
  fm as (select firm_id from public.clients where id = _client_id),
  ceiling as (
    select coalesce(pl.widgets,'{}'::text[]) as w
    from ent left join public.plan_levels pl
      on pl.scope='dashboard' and pl.key = ent.tier and pl.enabled
  ),
  base as (
    select coalesce(
      (select twc.excluded_widgets from public.tier_widget_config twc
        where twc.client_id is null and twc.firm_id = (select firm_id from fm)
          and twc.tier = (select tier from ent)),
      (select twc.excluded_widgets from public.tier_widget_config twc
        where twc.client_id is null and twc.firm_id is null
          and twc.tier = (select tier from ent)),
      '{}'::text[]) as w
  ),
  excluded as (
    select (select b.w from base b)
        || coalesce((select twc.excluded_widgets from public.tier_widget_config twc
                      where twc.client_id = _client_id
                        and twc.tier = (select tier from ent)), '{}'::text[]) as w
  )
  select coalesce(array(
    select distinct x from unnest((select c.w from ceiling c)) as x
    except
    select e from unnest((select ex.w from excluded ex)) as e
  ),'{}'::text[])
  ) end
$function$
;
CREATE OR REPLACE FUNCTION public.client_can_use_widget(_client_id uuid, _widget text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select app_private.assert_aal2();

  select _widget = any(public.client_allowed_widgets(_client_id))
$function$
;
CREATE OR REPLACE FUNCTION public.set_all_client_tiers(_firm_id uuid, _tier dashboard_tier, _include_billed boolean DEFAULT false, _reason text DEFAULT NULL::text)
 RETURNS TABLE(changed integer, skipped_billed integer, unchanged integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _c record;
  _sub public.client_subscriptions%ROWTYPE;
  _changed int := 0; _skipped int := 0; _same int := 0;
BEGIN
  perform app_private.assert_aal2();
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED' USING errcode='insufficient_privilege';
  END IF;

  -- Assigning dashboard tiers is an entitlement decision, not bookkeeping:
  -- super admins only.
  IF NOT app_private.is_super_admin(_uid) THEN
    RAISE EXCEPTION 'NO_ACCESS: only Positive Traction can set dashboard tiers'
      USING errcode='insufficient_privilege';
  END IF;

  -- The organisation's plan must permit the tier.
  IF NOT EXISTS (
    SELECT 1 FROM public.subscriptions s
    JOIN public.plan_levels p ON p.scope='firm' AND p.key = s.tier
    WHERE s.firm_id = _firm_id AND _tier::text = ANY(p.allowed_tiers)
  ) THEN
    RAISE EXCEPTION 'PLAN_DOES_NOT_PERMIT_TIER: this organisation''s plan does not include the % dashboard', _tier
      USING errcode='check_violation';
  END IF;

  FOR _c IN SELECT id, name FROM public.clients WHERE firm_id = _firm_id LOOP
    SELECT * INTO _sub FROM public.client_subscriptions
     WHERE client_id = _c.id ORDER BY created_at DESC LIMIT 1;

    IF _sub.id IS NOT NULL
       AND _sub.subscription_type IN ('paid','trial')
       AND NOT _include_billed THEN
      _skipped := _skipped + 1;
      CONTINUE;
    END IF;

    IF _sub.id IS NOT NULL AND _sub.dashboard_tier = _tier THEN
      _same := _same + 1;
      CONTINUE;
    END IF;

    IF _sub.id IS NOT NULL THEN
      UPDATE public.client_subscriptions
         SET dashboard_tier = _tier, updated_at = now()
       WHERE id = _sub.id;
    ELSE
      -- No row yet: record it as comped, not paid. Nothing is being charged,
      -- and inventing a 'paid' subscription with no Stripe behind it would
      -- corrupt billing once checkout is wired up.
      INSERT INTO public.client_subscriptions
        (client_id, subscription_type, status, dashboard_tier, comp_reason, comped_by, comped_at)
      VALUES (_c.id, 'free_forever', 'active', _tier,
              COALESCE(_reason,'Bulk tier assignment'), _uid, now());
    END IF;

    INSERT INTO public.audit_log (actor_user_id, firm_id, action, target_type, target_id, meta)
    VALUES (_uid, _firm_id, 'client_tier_changed', 'client', _c.id::text,
            jsonb_build_object('client_name', _c.name,
              'from', COALESCE(_sub.dashboard_tier::text,'basic'),
              'to', _tier::text, 'bulk', true, 'reason', _reason));
    _changed := _changed + 1;
  END LOOP;

  RETURN QUERY SELECT _changed, _skipped, _same;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.delete_client_report(_report_id uuid, _reason text DEFAULT NULL::text)
 RETURNS TABLE(deleted boolean, recipients_revoked integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _r public.client_reports%ROWTYPE;
  _n int := 0;
BEGIN
  perform app_private.assert_aal2();
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED' USING errcode='insufficient_privilege';
  END IF;

  SELECT * INTO _r FROM public.client_reports WHERE id = _report_id;
  IF _r.id IS NULL THEN
    RAISE EXCEPTION 'NOT_FOUND' USING errcode='no_data_found';
  END IF;

  -- Membership-only gate: owner of the client, or an active member of its
  -- organisation. Deliberately NOT app_private.user_can_manage_client, which
  -- admits read-only support grants.
  IF NOT EXISTS (
    SELECT 1 FROM public.clients c
     WHERE c.id = _r.client_id
       AND (c.owner_user_id = _uid
            OR (c.firm_id IS NOT NULL AND app_private.has_firm_access(_uid, c.firm_id)))
  ) THEN
    RAISE EXCEPTION 'NO_ACCESS' USING errcode='insufficient_privilege';
  END IF;

  IF _r.status IN ('final','sent') AND NOT app_private.is_super_admin(_uid) THEN
    RAISE EXCEPTION 'REPORT_IS_%: a report that has been finalised or sent can only be deleted by a super admin', upper(_r.status)
      USING errcode='insufficient_privilege';
  END IF;

  UPDATE public.report_recipients
     SET revoked_at = now()
   WHERE report_id = _report_id AND revoked_at IS NULL;
  GET DIAGNOSTICS _n = ROW_COUNT;

  INSERT INTO public.audit_log (actor_user_id, firm_id, action, target_type, target_id, meta)
  VALUES (_uid, _r.firm_id, 'client_report_deleted', 'client_reports', _report_id::text,
          jsonb_build_object('client_id',_r.client_id,'period_end',_r.period_end,
            'version',_r.version,'status',_r.status,'was_sent_at',_r.sent_at,
            'recipients_revoked',_n,'reason',_reason));

  DELETE FROM public.client_reports WHERE id = _report_id;

  RETURN QUERY SELECT true, _n;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.set_client_widget_enabled(_client_id uuid, _widget text, _enabled boolean)
 RETURNS TABLE(effective_tier text, is_enabled boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _tier text;
  _firm uuid;
  _excl text[];
  _in_tier boolean;
BEGIN
  perform app_private.assert_aal2();
  -- Membership-only gate: the caller must own the client or be an active
  -- member of the client's organisation. Deliberately NOT
  -- app_private.user_can_manage_client, which admits read-only support grants.
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'NO_ACCESS' USING errcode='insufficient_privilege';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.clients c
     WHERE c.id = _client_id
       AND (c.owner_user_id = _uid
            OR (c.firm_id IS NOT NULL AND app_private.has_firm_access(_uid, c.firm_id)))
  ) THEN
    RAISE EXCEPTION 'NO_ACCESS' USING errcode='insufficient_privilege';
  END IF;

  SELECT e.tier::text INTO _tier FROM public.client_entitlement(_client_id) e;
  SELECT c.firm_id INTO _firm FROM public.clients c WHERE c.id = _client_id;

  SELECT (_widget = ANY(pl.widgets)) INTO _in_tier
    FROM public.plan_levels pl
   WHERE pl.scope='dashboard' AND pl.key = _tier AND pl.enabled;

  IF _enabled AND NOT coalesce(_in_tier,false) THEN
    RAISE EXCEPTION 'NOT_IN_TIER: % is not part of the % dashboard', _widget, _tier
      USING errcode='check_violation';
  END IF;

  SELECT coalesce(twc.excluded_widgets,'{}') INTO _excl
    FROM public.tier_widget_config twc
   WHERE twc.client_id = _client_id AND twc.tier = _tier;

  IF _enabled THEN
    _excl := array_remove(coalesce(_excl,'{}'), _widget);
  ELSE
    _excl := (SELECT array(SELECT DISTINCT u FROM unnest(coalesce(_excl,'{}') || array[_widget]) u));
  END IF;

  INSERT INTO public.tier_widget_config (client_id, tier, widgets, excluded_widgets)
  VALUES (_client_id, _tier, '{}', _excl)
  ON CONFLICT (client_id, tier) WHERE client_id IS NOT NULL
  DO UPDATE SET excluded_widgets = _excl, updated_at = now();

  INSERT INTO public.audit_log (actor_user_id, firm_id, action, target_type, target_id, meta)
  VALUES (_uid, _firm, 'client_widget_toggled', 'client', _client_id::text,
          jsonb_build_object('widget',_widget,'enabled',_enabled,'tier',_tier));

  RETURN QUERY SELECT _tier, public.client_can_use_widget(_client_id, _widget);
END;
$function$
;
CREATE OR REPLACE FUNCTION app_private.firm_subscription_lapsed(_firm_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when auth.uid() is not null
               and not public.user_can_access_firm(auth.uid(), _firm_id)
               and not app_private.is_super_admin(auth.uid())
          then false else (
  select case
    -- Positive Traction's own organisation is never charged and never lapses.
    when exists (select 1 from public.firms f where f.id=_firm_id and f.is_always_free) then false
    else exists (
      select 1 from public.subscriptions s
      where s.firm_id = _firm_id
        and (
          (s.status = 'trialing' and s.trial_ends_at is not null and s.trial_ends_at < now())
          or s.status in ('canceled','unpaid','incomplete_expired')
          or (s.status = 'past_due' and s.current_period_end is not null
              and s.current_period_end < now())
        )
    )
  end
  ) end
$function$
;
CREATE OR REPLACE FUNCTION public.firm_access_path(_user_id uuid, _firm_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when _user_id is null or _firm_id is null then 'none'
    when app_private.has_firm_access(_user_id, _firm_id) then 'member'
    when app_private.platform_staff_can_access_firm(_user_id, _firm_id) then 'support_grant'
    else 'none'
  end
$function$
;
CREATE OR REPLACE FUNCTION public.assert_client_write_access(_client_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private'
AS $function$
declare _uid uuid := auth.uid();
begin
  perform app_private.assert_aal2();
  if _uid is null then
    raise exception 'NO_ACCESS' using errcode = 'insufficient_privilege';
  end if;
  if not exists (
    select 1 from public.clients c
     where c.id = _client_id
       and (c.owner_user_id = _uid
            or (c.firm_id is not null and app_private.has_firm_access(_uid, c.firm_id)))
  ) then
    raise exception 'NO_ACCESS' using errcode = 'insufficient_privilege';
  end if;
end;
$function$
;
CREATE OR REPLACE FUNCTION app_private.is_aal2()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select case
    -- No HTTP request context: cron, migrations, direct maintenance. These are
    -- system contexts, not a signed-in person.
    when nullif(current_setting('request.jwt.claims', true), '') is null then true
    -- Service role (webhooks, OAuth callback, email queue, nightly refresh)
    -- already bypasses row level security, so MFA is not the control there.
    when coalesce(
           nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
           ''
         ) = 'service_role' then true
    else coalesce(
           nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'aal',
           ''
         ) = 'aal2'
  end
$function$
;
CREATE OR REPLACE FUNCTION app_private.assert_aal2()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
  if not app_private.is_aal2() then
    raise exception 'MFA_REQUIRED' using errcode = 'insufficient_privilege';
  end if;
  return true;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.online_users(_window_minutes integer DEFAULT 5)
 RETURNS TABLE(user_id uuid, display_name text, email text, is_super_admin boolean, has_mfa boolean, last_seen_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  PERFORM app_private.assert_aal2();
  IF NOT app_private.me_is_super_admin() THEN
    RAISE EXCEPTION 'FORBIDDEN' USING errcode = 'insufficient_privilege';
  END IF;
  RETURN QUERY
    SELECT p.user_id,
           pr.display_name,
           u.email::text,
           EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = p.user_id AND r.role='super_admin'),
           EXISTS (SELECT 1 FROM auth.mfa_factors f WHERE f.user_id = p.user_id AND f.status='verified'),
           p.last_seen_at
    FROM public.user_presence p
    LEFT JOIN public.profiles pr ON pr.id = p.user_id
    LEFT JOIN auth.users u ON u.id = p.user_id
    WHERE p.last_seen_at > now() - make_interval(mins => greatest(1, least(_window_minutes, 60)))
    ORDER BY p.last_seen_at DESC;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.set_profile_display_name_admin(_target_user_id uuid, _display_name text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_name text;
  v_old_name text;
BEGIN
  PERFORM app_private.assert_aal2();
  IF NOT app_private.me_is_super_admin() THEN
    RAISE EXCEPTION 'FORBIDDEN' USING errcode = 'insufficient_privilege';
  END IF;

  v_name := btrim(_display_name);
  IF v_name IS NULL OR length(v_name) < 1 OR length(v_name) > 80
     OR v_name ~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
    RAISE EXCEPTION 'INVALID_DISPLAY_NAME' USING errcode = '22023';
  END IF;

  SELECT display_name INTO v_old_name
  FROM public.profiles
  WHERE id = _target_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PROFILE_NOT_FOUND' USING errcode = 'P0002';
  END IF;

  UPDATE public.profiles
  SET display_name = v_name
  WHERE id = _target_user_id;

  INSERT INTO public.audit_log (
    actor_user_id, action, target_type, target_id, meta
  ) VALUES (
    auth.uid(),
    'profile_name_changed',
    'user',
    _target_user_id::text,
    jsonb_build_object('old_value', v_old_name, 'new_value', v_name)
  );

  RETURN v_name;
END;
$function$
;
CREATE OR REPLACE FUNCTION app_private.practice_firm_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select value::uuid from app_private.platform_settings where key = 'practice_firm_id'
$function$
;
CREATE OR REPLACE FUNCTION app_private.user_can_write_client(_user_id uuid, _client_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when auth.uid() is not null and _user_id is distinct from auth.uid() then false else (
    select exists (
      select 1 from public.clients c
      where c.id = _client_id
        and (c.owner_user_id = _user_id
             or (c.firm_id is not null and app_private.has_firm_access(_user_id, c.firm_id)))
    )
  ) end
$function$
;
CREATE OR REPLACE FUNCTION app_private.client_for_tenant(_tenant_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare _n int; _client uuid;
begin
  select count(distinct cxo.client_id) into _n
  from public.client_xero_orgs cxo
  join public.xero_connections xc on xc.id = cxo.xero_connection_id
  where xc.tenant_id = _tenant_id;

  if coalesce(_n,0) = 0 then
    return null;
  elsif _n > 1 then
    raise exception 'This Xero file is linked to more than one client.'
      using errcode = 'raise_exception';
  end if;

  select distinct cxo.client_id into _client
  from public.client_xero_orgs cxo
  join public.xero_connections xc on xc.id = cxo.xero_connection_id
  where xc.tenant_id = _tenant_id;
  return _client;
end;
$function$
;
CREATE OR REPLACE FUNCTION app_private.canonical_widget(_widget text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$ select case when _widget = 'true_breakeven' then 'accounting_breakeven' else _widget end $function$
;
CREATE OR REPLACE FUNCTION app_private.tier_ceiling_widgets(_tier text)
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    nullif((select pl.widgets from public.plan_levels pl
             where pl.scope = 'dashboard' and pl.key = _tier and pl.enabled), '{}'::text[]),
    case _tier
      when 'basic' then array['health','receivables','payables','pnl','notes','unreconciled']
      else array['health','receivables','payables','pnl','notes','unreconciled','superannuation',
                 'accounting_breakeven','true_breakeven','cashflow','cashflow_scenario','xero_audit',
                 'loan_consolidation','gst_reconciliation','transaction_search']
    end)
$function$
;
CREATE OR REPLACE FUNCTION app_private.effective_widgets_for_client(_client_id uuid, _tier text)
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with fm as (select firm_id from public.clients where id = _client_id),
  base as (
    select coalesce(
      (select twc.excluded_widgets from public.tier_widget_config twc
        where twc.client_id is null and twc.firm_id = (select firm_id from fm) and twc.tier = _tier),
      (select twc.excluded_widgets from public.tier_widget_config twc
        where twc.client_id is null and twc.firm_id is null and twc.tier = _tier),
      '{}'::text[]) as w
  ),
  excluded as (
    select (select b.w from base b)
        || coalesce((select twc.excluded_widgets from public.tier_widget_config twc
                      where twc.client_id = _client_id and twc.tier = _tier), '{}'::text[]) as w
  )
  select coalesce(array(
    select distinct x from unnest(app_private.tier_ceiling_widgets(_tier)) as x
    except
    select e from unnest((select ex.w from excluded ex)) as e
  ), '{}'::text[])
$function$
;
CREATE OR REPLACE FUNCTION app_private.client_xero_files_used(_client_id uuid, _exclude_link_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(*)::integer
  from public.client_xero_orgs cxo
  join public.xero_connections xc on xc.id = cxo.xero_connection_id
  where cxo.client_id = _client_id
    and (_exclude_link_id is null or cxo.id <> _exclude_link_id)
    and coalesce(xc.status, 'connected') <> 'disconnected'
$function$
;
CREATE OR REPLACE FUNCTION public.audit_table_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  _old jsonb := case when tg_op = 'INSERT' then '{}'::jsonb else to_jsonb(old) end;
  _new jsonb := case when tg_op = 'DELETE' then '{}'::jsonb else to_jsonb(new) end;
  _changed jsonb := '{}'::jsonb;
  _k text;
  _firm uuid;
  _rowid text;
begin
  for _k in
    select key from jsonb_each(_old)
    union
    select key from jsonb_each(_new)
  loop
    if (_old -> _k) is distinct from (_new -> _k) then
      _changed := _changed || jsonb_build_object(
        _k, jsonb_build_object('from', _old -> _k, 'to', _new -> _k));
    end if;
  end loop;

  _rowid := coalesce(_new ->> 'id', _old ->> 'id');
  _firm := nullif(
    coalesce(
      _new ->> 'firm_id',
      _old ->> 'firm_id',
      case when tg_table_name = 'firms' then coalesce(_new ->> 'id', _old ->> 'id') end
    ), '')::uuid;

  insert into public.audit_log (actor_user_id, firm_id, action, target_type, target_id, meta)
  values (
    auth.uid(),
    _firm,
    'record_' || lower(tg_op),
    tg_table_name,
    _rowid,
    jsonb_build_object('table', tg_table_name, 'op', tg_op, 'changed', _changed)
  );
  return null;
end;
$function$
;
